package com.enterprise.procurement.controller.v2;
import com.enterprise.procurement.business.PurchaseBusinessService; import com.enterprise.procurement.dto.*; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/approvals") public class ApprovalController {private final PurchaseBusinessService s; public ApprovalController(PurchaseBusinessService s){this.s=s;} @GetMapping("/pending") @PreAuthorize("hasAnyRole('ADMIN','APPROVER','MANAGER')") public ApiResponse<?> pending(java.security.Principal p){return ApiResponse.ok(s.pending(p.getName()));} @PostMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','APPROVER','MANAGER')") public ApiResponse<?> approve(@PathVariable Long id,@Valid @RequestBody PurchaseRequestDtos.Approval d,java.security.Principal p){return ApiResponse.ok(s.approve(id,p.getName(),d));}}
